            "dtStart": {
              "type": "string",
              "description": "当天下一条日程开始时间",
              "sampleValue": "10:30"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_car.png",
      "description": "汽车/打车彩色图标，适合用于雨天打车卡片的主视觉识别。"
    }
  ]
}

